ALERT HighCPU
  IF node_cpu_usage_percent > 80
  FOR 5m
  LABELS { severity="warning" }
  ANNOTATIONS { summary="CPU por encima de 80% por más de 5 minutos" }

ALERT CriticalCPU
  IF node_cpu_usage_percent > 95
  FOR 1m
  LABELS { severity="critical" }
  ANNOTATIONS { summary="CPU crítico - intervención inmediata necesaria" }
